  "dallendyshe1.text[3]": { al: "mushkonja hap gojën.", en: "The mosquito opens its mouth." },
  "dallendyshe1.text[4]": { al: "ti sheh gjuhën e mushkonjës.", en: "You see the mosquito's tongue." },
  "dallendysheFund.text[0]": { al: "ti pre gjuhën e mushkonjës.", en: "You cut out the mosquito's tongue." },
  "dallendysheFund.text[1]": { al: "gjarpri mallkon dallëndyshen.", en: "The serpent curses the swallow." },
  "dallendysheFund.text[2]": { al: "njeriu është i sigurt. ti rri në shtëpi.", en: "Humankind is safe. You make your home among people." },
